import{_ as t,o,c as a,ai as s}from"./chunks/framework.Cabe_Szf.js";const p=JSON.parse('{"title":"Decision Lab","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://lognebudo.github.io/llmxray/docs/en/guide/decision-lab.html"}]]},"headers":[],"relativePath":"en/guide/decision-lab.md","filePath":"en/guide/decision-lab.md","lastUpdated":1791749853000}'),i={name:"en/guide/decision-lab.md"};function n(r,e,d,h,l,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="decision-lab" tabindex="-1">Decision Lab <a class="header-anchor" href="#decision-lab" aria-label="Permalink to &quot;Decision Lab&quot;">​</a></h1><p>The <strong>Decision Lab</strong> asks a decision model typed questions about a situation and shows the probability behind every answer.</p><p><strong>Sidebar item:</strong> Decision Lab (below Cache Lab) <strong>Route:</strong> <code>/decision-lab</code><strong>Added in:</strong> v0.7.0 (October 2026) <strong>Requires:</strong> Ollama 0.35.1 or newer, and a decision model (<code>nimble</code>, <code>tev1</code>, <code>clef-flash</code> or <code>clef</code>)</p><h2 id="what-s-the-point" tabindex="-1">What&#39;s the point? <a class="header-anchor" href="#what-s-the-point" aria-label="Permalink to &quot;What&#39;s the point?&quot;">​</a></h2><p>A decision model does not write text. You give it a <strong>state</strong> (a ticket, a message, a log line, a document) and one or more <strong>questions</strong>, and it returns:</p><table tabindex="0"><thead><tr><th>Question type</th><th>What comes back</th></tr></thead><tbody><tr><td><strong>Choice</strong></td><td>The chosen candidate, a probability for <em>every</em> candidate, and a confidence</td></tr><tr><td><strong>Yes / no probability</strong></td><td>A single probability that the condition holds</td></tr><tr><td><strong>Score on a scale</strong></td><td>The expected position on your ordered scale, a probability per step, and a confidence</td></tr></tbody></table><p>The probabilities are the model&#39;s own output distribution over the candidates, not a number parsed out of prose. That is what makes them worth looking at: a chat model asked &quot;is this urgent?&quot; says <em>yes</em>; a decision model says <em>0.99</em>, and for a borderline ticket it says <em>0.55</em>, and you can see the difference.</p><p>Ollama serves these models on <code>/v1/systemone</code> (added in 0.35.1). They report <code>decision</code> as their <strong>only</strong> capability, so LLMxRay keeps them out of every chat and embedding selector and lists them here instead. Sending one a chat request does not fail cleanly, it answers with fragments of its own schema, which is exactly why the filter exists.</p><h2 id="using-the-page" tabindex="-1">Using the page <a class="header-anchor" href="#using-the-page" aria-label="Permalink to &quot;Using the page&quot;">​</a></h2><ol><li>Pick a decision model. If none is installed, pull one from the Models page; <code>tev1:0.8b</code> is the smallest.</li><li>Describe the <strong>state</strong>. Every question is asked about this one text.</li><li>Edit the <strong>questions</strong>. Each has an answer key (what the result comes back under), a type, instructions, and for choice and score types a list of candidates: <ul><li><strong>Choice</strong>: one per line as <code>name: description</code>.</li><li><strong>Score</strong>: one per line, lowest first. The order <em>is</em> the scale.</li><li>Ollama accepts 2 to 26 candidates and 1 to 64 questions per request; the page tells you before sending when a question is outside that.</li></ul></li><li><strong>Decide</strong>. The answers appear on the right as bars, the chosen candidate highlighted, with input and output token counts and the round-trip time.</li></ol><p>The page opens with a worked sample: a support ticket asked three ways, one question of each type. It is the request that was run live while verifying Ollama 0.40.3.</p><h2 id="reading-the-answers" tabindex="-1">Reading the answers <a class="header-anchor" href="#reading-the-answers" aria-label="Permalink to &quot;Reading the answers&quot;">​</a></h2><ul><li><strong>Choice</strong>: bars are sorted by probability. The highlighted one is the model&#39;s choice. Confidence is the model&#39;s own figure, reported alongside.</li><li><strong>Yes / no</strong>: shown as a <em>yes</em> and a <em>no</em> bar that sum to 1.</li><li><strong>Score</strong>: bars stay in scale order, because position is the meaning. The highlighted step is the most probable one. The <em>score</em> number is the expected position (probability-weighted), so it can fall between two steps: a 2.37 on a four-step scale means &quot;major, leaning toward full outage&quot;.</li></ul><h2 id="what-this-page-does-not-do" tabindex="-1">What this page does not do <a class="header-anchor" href="#what-this-page-does-not-do" aria-label="Permalink to &quot;What this page does not do&quot;">​</a></h2><p>It does not stream (the endpoint never does), it does not keep history, and it does not send images yet, although <code>clef</code> and <code>clef-flash</code> accept them. It is an observatory for what a decision model actually returns, nothing more.</p>',15)])])}const u=t(i,[["render",n]]);export{p as __pageData,u as default};
